<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Kanban Board</title>
    <style>
        :root { --bg-color: #f4f5f7; --col-bg: #fff; --header-hl: #dfe1e6; --text-main: #172b4d; }

        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background-color: var(--bg-color); color: var(--text-main); margin: 0; padding: 2rem; display: flex; justify-content: center;}

        .board-wrapper { width: 100%; max-width: 1200px; }

        /* Input Area */
        .input-area { display: flex; gap: 10px; margin-bottom: 30px; align-items: center; }
        #new-card { padding: 8px 12px; border-radius: 4px; border: 1px solid #dfe1e6; font-size: 1rem; width: 300px;}
        #add-card { background-color: var(--text-main); color: white; border: none; padding: 8px 12px; border-radius: 4px; cursor: pointer; }

        /* Board Columns */
        .board-layout { display: flex; gap: 16px; align-items: flex-start;}

        #col-todo, #col-doing, #col-done { background-color: var(--col-bg); border-radius: 8px; box-shadow: inset 0 2px 4px rgba(9,30,66,.05), 0 2px 4px rgba(9,30,66,.15); display: flex; flex-direction: column;}

        /* Headers & Counts */
        .col-header { padding: 1rem; font-weight: bold; border-bottom: 1px solid var(--header-hl);}

        .count { margin-left: auto; background-color: #dfe1e6; padding: 2px 8px; border-radius: 12px; font-size: 0.9rem;}

        /* Card Container */
        .card-container { min-height: 400px; padding: 0.5rem;}

        /* Cards & Buttons */
        .card { background-color: var(--col-bg); border-radius: 6px; box-shadow: 0 1px 2px rgba(9,30,66,.25); margin-bottom: 8px; padding: 1rem; position: relative;}

        /* Layout Card content flexly to push delete button */
        .card-content { display: flex; justify-content: space-between; align-items: center; width: 100%; }

        .delete-btn { font-family: sans-serif; text-decoration: underline; background: transparent; border: none; color: #dfe1e6; cursor: pointer;}
        .delete-btn:hover { color: var(--text-main); opacity: 0.7; }

    </style>
</head>
<body>

<div class="board-wrapper">
    <div class="input-area">
        <input type="text" id="new-card" placeholder="Add a new card...">
        <button id="add-card">Add Card</button>
    </div>

    <div class="board-layout">

        <!-- Column 1: To Do -->
        <div id="col-todo" class="column">
            <div class="col-header">To Do <span class="count"></span></div>
            <div class="card-container"></div>
        </div>

        <!-- Column 2: Doing -->
        <div id="col-doing" class="column">
            <div class="col-header">Doing <span class="count"></span></div>
            <div class="card-container"></div>
        </div>

        <!-- Column 3: Done -->
        <div id="col-done" class="column">
            <div class="col-header">Done <span class="count"></span></div>
            <div class="card-container"></div>
        </div>

    </div>
</div>

<script>
(function() {
    // State: Array of objects per column key. Each object has 'id' and 'text'.
    let state = { todo: [], doing: [], done: [] };

    const newCardInput = document.getElementById('new-card');
    const addCardBtn = document.getElementById('add-card');
    // Select columns by specific IDs as required
    const cols = [document.getElementById('col-todo'), document.getElementById('col-doing'), document.getElementById('col-done')];

    function loadState() {
        try {
            const saved = localStorage.getItem('kanban_state_v1');
            if (saved) state = JSON.parse(saved);
        } catch(e) { console.error("Load failed", e); }
    }

    function saveState() {
        localStorage.setItem('kanban_state_v1', JSON.stringify(state));
    }

    function renderBoard() {
        cols.forEach(col => {
            const colKey = col.id.replace('col-', ''); // 'todo' etc.
            if (!state[colKey]) return; 
            const container = col.querySelector('.card-container');

            while (container.firstChild) {
                container.removeChild(container.firstChild);
            }

            state[colKey].forEach(cardData => {
                const el = createCardElement(cardData.id, cardData.text);
                container.appendChild(el);
            });
        });
        updateCounts();
    }

    function createCardElement(id, text) {
        const el = document.createElement('div');
        el.className = 'card';
        el.draggable = true; 
        el.id = `c-${id}`;

        // Card content wrapper for flex layout of title and button
        const wrap = document.createElement('div');
        wrap.className = 'card-content';

        const span = document.createElement('span');
        span.textContent = text;

        const delBtn = document.createElement('button');
        delBtn.className = 'delete-btn';
        delBtn.innerHTML = '&times; Delete'; // Text visible

        delBtn.onclick = (e) => { 
            e.stopPropagation(); 
            deleteCard(id); 
        };

        wrap.appendChild(span);
        wrap.appendChild(delBtn);
        el.appendChild(wrap);

        return el;
    }

    function updateCounts() {
        cols.forEach(col => {
            const container = col.querySelector('.card-container');
            if(container) {
                const countEl = col.querySelector('.count');
                countEl.textContent = container.children.length;
            }
        });
    }

    function addCard(text) {
        text = text.trim();
        if (!text) return; 

        const id = Date.now(); 
        state.todo.push({id, text});

        saveState();
        renderBoard(); 

        newCardInput.value = ''; 
    }

    function deleteCard(id) {
        ['todo', 'doing', 'done'].forEach(col => {
            state[col] = state[col].filter(card => card.id !== id);
        });

        saveState();
        renderBoard(); 
    }

    // Drag & Drop Logic (Handlers ON Columns as required)
    let draggedId = null;

    cols.forEach(col => {
        // dragstart on COLUMN via delegation
        col.addEventListener('dragstart', function(e) {
            const targetEl = e.target.closest('.card');
            if (!targetEl || !targetEl.id.startsWith('c-')) return;

            draggedId = parseInt(targetEl.id.split('-')[1]);
        });

        col.addEventListener('dragover', function(e) {
            e.preventDefault(); // Required to allow dropping
        });

        col.addEventListener('drop', function(e) {
            e.preventDefault();

            if (draggedId === null || draggedId === undefined) return;

            const movingEl = document.getElementById(`c-${draggedId}`);
            const targetColKey = col.id.replace('col-', ''); 

            if (!movingEl) {
                console.error("Card element not found for ID:", draggedId);
                draggedId = null;
                return;
            }

            // Determine source column of this element before moving it in DOM
            const parentContainer = movingEl.parentElement;
            let sourceColKey = null;

            if (parentContainer && parentContainer.className.includes('card-container')) {
                 sourceColKey = parentContainer.closest('.column').id.replace('col-', '');
            }

            // Only move logic applies to different columns or reordering within? 
            // Moving element physically updates DOM. State update ensures persistence matches visual location on reload (since we store full structure).

            if (sourceColKey && sourceColKey !== targetColKey) {
                const cardIndex = state[sourceColKey].findIndex(c => c.id === draggedId);
                if (cardIndex > -1) {
                    const [movedCard] = state[sourceColKey].splice(cardIndex, 1); 
                    movedCard.col = targetColKey; // Optional metadata update? Not strictly needed for persistence as key determines placement in renderBoard loop

                    state[targetColKey].push(movedCard); 

                    saveState();
                }

                const targetContainer = col.querySelector('.card-container');
                if(targetContainer && movingEl.parentNode !== targetContainer) {
                     targetContainer.appendChild(movingEl);
                     updateCounts(); 
                } else if (!targetColKey || sourceColKey === targetColKey) {
                    // Drop on same column - usually no move needed for persistence logic, but visual might need reorder (not strictly enforced by prompt).
                }

            } 

            draggedId = null;
        });
    });

    addCardBtn.addEventListener('click', () => {
        addCard(newCardInput.value);
    });

    newCardInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
            addCard(newCardInput.value);
        }
    });

    loadState();
    renderBoard(); 

})();
</script>
</body>
</html>
